      "description": "Users report severe battery depletion and device freezing immediately after updating to iOS 11."
    },
    {
      "cluster": 1,
      "name": "Auto-Brightness Toggle Missing",
      "description": "Customers are frustrated by the inability to disable automatic screen brightness adjustments in iOS 11."
    },
    {
      "cluster": 2,
      "name": "Apple Watch Update Failures",
      "description": "Users experience stuck updates, connectivity issues, and hardware malfunctions with their Apple Watch."
    },
    {
      "cluster": 3,
      "name": "FaceTime Call Routing Errors",
      "description": "Users report FaceTime calls connecting to wrong recipients or failing to work entirely on new devices."
    },
    {
      "cluster": 4,
      "name": "Maps GPS Inaccuracy",
      "description": "Customers report that Apple Maps and GPS location services provide incorrect or unstable directions while driving."
    },
    {
      "cluster": 5,
      "name": "Siri Voice Recognition Issues",
      "description": "Users complain that Siri is unresponsive, has a distorted voice, or fails to perform basic commands."
    },
    {
      "cluster": 6,
      "name": "iBooks PDF Download Failures",
      "description": "Users cannot download, open, or retain PDF and EPUB files in iBooks and Pages after the iOS 11 update."
    },
    {
      "cluster": 7,
      "name": "MacBook Hardware Malfunctions",
      "description": "Owners report unexpected shutdowns, system crashes, and hardware noises on MacBook and iMac devices."
    },
    {
      "cluster": 8,
      "name": "Wi-Fi Auto-Connect Glitch",
      "description": "Users report that Wi-Fi turns on by itself or lags significantly after updating to iOS 11."
    },
    {
      "cluster": 9,
      "name": "Apple Phishing Scams",
      "description": "Users report receiving fake emails and texts impersonating Apple to solicit payments or personal data."
    },
    {
      "cluster": 10,
