      "description": "Users experience frozen video frames or missing audio when using the iOS 11 screen recording feature."
    },
    {
      "cluster": 11,
      "name": "Apple TV HDR Settings",
      "description": "Users request options to disable HDR color conversion and adjust playback speed on Apple TV."
    }
  ]
